import{_ as n,I as s,c as o,o as t,a5 as a,b as c,w as i,a as d,J as l,a6 as u}from"./chunks/framework.BmNIwhaK.js";const y=JSON.parse('{"title":"Server Unattended Batch Scheduler and Distributed Lock-Based Device Farm Operations","description":"Redis distributed lock and scheduler architecture for executing conflict-free overnight unattended regression tests across on-premises physical device racks and Docker virtual devices.","frontmatter":{"title":"Server Unattended Batch Scheduler and Distributed Lock-Based Device Farm Operations","shortTitle":"Device Farm Scheduler","category":"Mobile Test Engineering","sort":23,"description":"Redis distributed lock and scheduler architecture for executing conflict-free overnight unattended regression tests across on-premises physical device racks and Docker virtual devices.","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/en/synceta/device-farm-scheduler"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/synceta/device-farm-scheduler"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/synceta/device-farm-scheduler"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/synceta/device-farm-scheduler"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/synceta/device-farm-scheduler"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"Server Unattended Batch Scheduler and Distributed Lock-Based Device Farm Operations | Empasy Docs"}],["meta",{"property":"og:description","content":"Redis distributed lock and scheduler architecture for executing conflict-free overnight unattended regression tests across on-premises physical device racks and Docker virtual devices."}],["meta",{"property":"og:url","content":"https://doc.empasy.com/en/synceta/device-farm-scheduler"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Server Unattended Batch Scheduler and Distributed Lock-Based Device Farm Operations | Empasy Docs"}],["meta",{"name":"twitter:description","content":"Redis distributed lock and scheduler architecture for executing conflict-free overnight unattended regression tests across on-premises physical device racks and Docker virtual devices."}]]},"headers":[],"relativePath":"en/synceta/device-farm-scheduler.md","filePath":"en/synceta/device-farm-scheduler.md","lastUpdated":1795293539000}'),h={name:"en/synceta/device-farm-scheduler.md"};function g(p,e,m,f,v,k){const r=s("Mermaid");return t(),o("div",null,[e[1]||(e[1]=a('<h1 id="server-unattended-batch-scheduler-and-distributed-lock-based-device-farm-operations" tabindex="-1">Server Unattended Batch Scheduler and Distributed Lock-Based Device Farm Operations <a class="header-anchor" href="#server-unattended-batch-scheduler-and-distributed-lock-based-device-farm-operations" aria-label="Permalink to “Server Unattended Batch Scheduler and Distributed Lock-Based Device Farm Operations”">​</a></h1><h2 id="_1-overview-and-large-scale-testing-challenges" tabindex="-1">1. Overview and Large-Scale Testing Challenges <a class="header-anchor" href="#_1-overview-and-large-scale-testing-challenges" aria-label="Permalink to “1. Overview and Large-Scale Testing Challenges”">​</a></h2><p>Moving beyond 1:1 testing on a developer&#39;s local PC, running <strong>overnight unattended regression tests</strong> against dozens of physical mobile devices deployed in-house (Android racks, Mac mini-based iOS racks, and Docker redroid virtual device pools) introduces the following concurrency challenges:</p><ol><li><strong>Device Contention</strong>: Different projects or build pipelines simultaneously accessing the same physical device, causing tests to interfere with one another or terminate abnormally.</li><li><strong>Device Deadlock on Abnormal Termination</strong>: If a runner process is forcefully terminated during test execution, the device session remains locked, leaving subsequent tests waiting indefinitely.</li><li><strong>Visual False Positives from Notches and Status Bars</strong>: Battery level indicators, clock minute/second changes, and front camera notch areas causing pixel comparisons to falsely report failures even when no actual app defect exists.</li></ol><p><code>SyncETA</code> achieves unattended automation for large-scale device farms through a <strong>NestJS Scheduler &amp; BullMQ Queue</strong>, <strong>Redis Distributed Locks</strong>, and an <strong>Intelligent Region Masking Engine</strong>.</p>',5)),(t(),c(u,null,{default:i(()=>[l(r,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Cron%5B%22Scheduled%20Batch%20Scheduler%20(Cron)%22%5D%20--%3E%20Queue%5B%22BullMQ%20Job%20Queue%20(Redis)%22%5D%0A%20%20%20%20CI%5B%22CI%2FCD%20Webhook%20Trigger%22%5D%20--%3E%20Queue%0A%0A%20%20%20%20Queue%20--%3E%20Worker%5B%22Scheduler%20Job%20Dispatcher%20(WorkerHost)%22%5D%0A%20%20%20%20Worker%20--%3E%20Lock%7B%22Acquire%20Redis%20Distributed%20Lock%20(device%3Alock%3Aid)%22%7D%0A%0A%20%20%20%20Lock%20--%20%22Acquisition%20Failed%20(In%20Use)%22%20--%3E%20Retry%5B%22Requeue%20at%20Lower%20Priority%20with%20Exponential%20Backoff%22%5D%0A%20%20%20%20Lock%20--%20%22Acquisition%20Succeeded%22%20--%3E%20Exec%5B%22Parallel%20Scenario%20Execution%20on%20Target%20Device%22%5D%0A%0A%20%20%20%20subgraph%20RunProcess%20%5B%22Execution%20and%20Quality%20Verification%20Pipeline%22%5D%0A%20%20%20%20%20%20%20%20Exec%20--%3E%20Replay%5B%22Unattended%20Gesture%20Replay%22%5D%0A%20%20%20%20%20%20%20%20Replay%20--%3E%20Mask%5B%22Auto-Masking%20of%20Notch%20%2F%20Status%20Bar%20Regions%22%5D%0A%20%20%20%20%20%20%20%20Mask%20--%3E%20Visual%5B%22Pixelmatch-Based%20Visual%20Regression%20Verdict%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20RunProcess%20--%3E%20Release%5B%22Heartbeat%20Expiration%20and%20Safe%20Distributed%20Lock%20Release%22%5D%0A%20%20%20%20Release%20--%3E%20Report%5B%22Test%20Result%20Statistics%20and%20Failure%20Snapshot%20Report%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_2-redis-distributed-lock-based-device-contention-control" tabindex="-1">2. Redis Distributed Lock-Based Device Contention Control <a class="header-anchor" href="#_2-redis-distributed-lock-based-device-contention-control" aria-label="Permalink to “2. Redis Distributed Lock-Based Device Contention Control”">​</a></h2><p>To prevent duplicate control of the same device, SyncETA applies a Redis-based distributed locking mechanism.</p><ul><li><strong>Lock Acquisition Specification</strong>: <ul><li>Key format: <code>device:lock:{platform}:{deviceId}</code> (e.g., <code>device:lock:android:emulator-5554</code>)</li><li>Atomic operation: Redis <code>SET key value NX PX 120000</code> (default timeout: 120 seconds)</li></ul></li><li><strong>Heartbeat Renewal and Safe Release</strong>: <ul><li>The test runner process renews the lock&#39;s Time-To-Live (TTL) every 30 seconds.</li><li>Even if a network disconnection or abnormal process crash occurs, the Redis key automatically expires (Auto-Release) after 120 seconds, preventing the device from becoming permanently locked.</li></ul></li></ul><hr><h2 id="_3-notch-and-status-bar-auto-masking-visual-regression-verification" tabindex="-1">3. Notch and Status Bar Auto-Masking Visual Regression Verification <a class="header-anchor" href="#_3-notch-and-status-bar-auto-masking-visual-regression-verification" aria-label="Permalink to “3. Notch and Status Bar Auto-Masking Visual Regression Verification”">​</a></h2><p>To eliminate unnecessary false positives during pixel-level visual regression testing of mobile screens, a 3-stage masking pipeline is executed.</p><ol><li><strong>Top Status Bar Static Masking</strong>: <ul><li>Excludes the top bar height collected from each device&#39;s OS configuration (e.g., Android <code>24dp</code>, iOS Dynamic Island <code>54pt</code>) from comparison (Zero-Alpha processing).</li></ul></li><li><strong>Bottom Gesture Navigation Bar (Home Bar) Masking</strong>: <ul><li>When not in full-screen mode, masks the bottom <code>16~20dp</code> system bar region.</li></ul></li><li><strong>Pixelmatch-Based Effective Threshold Comparison</strong>: <ul><li>Runs the <code>pixelmatch</code> library against the main content region excluding the masked areas, and marks the test as passed if the pixel difference ratio falls within a predefined tolerance threshold (e.g., <code>0.1%</code> or less).</li></ul></li></ol><hr><h2 id="_4-overnight-batch-pipeline-operating-standards" tabindex="-1">4. Overnight Batch Pipeline Operating Standards <a class="header-anchor" href="#_4-overnight-batch-pipeline-operating-standards" aria-label="Permalink to “4. Overnight Batch Pipeline Operating Standards”">​</a></h2><ul><li><strong>Scheduling Cycle</strong>: Executes full regression tests across all registered enterprise scenarios daily between <code>02:00</code> and <code>05:00</code>.</li><li><strong>Failure Isolation and Preservation</strong>: <ul><li>Immediately upon detecting a test failure, captures the current screen and bundles the preceding 10 seconds of Logcat or system console logs for persistent storage in S3/MinIO.</li><li>Automatically attaches a Diff image overlaying the differences between the failed screen and the baseline screen to the report so the development team can immediately identify the root cause the following morning.</li></ul></li></ul>',11))])}const D=n(h,[["render",g]]);export{y as __pageData,D as default};
